CREATE TABLE public.profiles (id uuid PRIMARY KEY, handle text UNIQUE NOT NULL, display_name text NOT NULL, campus text NOT NULL DEFAULT 'UNILAG', bio text NOT NULL DEFAULT '', joined_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.profiles TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public profiles" ON public.profiles FOR SELECT TO anon, authenticated USING (true); CREATE POLICY "Own profile insert" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid()); CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.posts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author_id uuid, handle text NOT NULL, campus text NOT NULL, flair text NOT NULL DEFAULT 'Campus', title text NOT NULL, body text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'text', media_url text, votes integer NOT NULL DEFAULT 0, comments integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.posts TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.posts TO authenticated; GRANT ALL ON public.posts TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.posts_id_seq TO authenticated, service_role; ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public posts" ON public.posts FOR SELECT TO anon, authenticated USING (true); CREATE POLICY "Own posts insert" ON public.posts FOR INSERT TO authenticated WITH CHECK (author_id = auth.uid()); CREATE POLICY "Own posts update" ON public.posts FOR UPDATE TO authenticated USING (author_id = auth.uid()) WITH CHECK (author_id = auth.uid()); CREATE POLICY "Own posts delete" ON public.posts FOR DELETE TO authenticated USING (author_id = auth.uid());
CREATE TABLE public.post_votes (user_id uuid NOT NULL, post_id bigint NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, value smallint NOT NULL CHECK (value IN (-1,1)), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.post_votes TO authenticated; GRANT ALL ON public.post_votes TO service_role; ALTER TABLE public.post_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own votes read" ON public.post_votes FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Own votes insert" ON public.post_votes FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Own votes update" ON public.post_votes FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE POLICY "Own votes delete" ON public.post_votes FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.bookmarks (user_id uuid NOT NULL, post_id bigint NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.bookmarks TO authenticated; GRANT ALL ON public.bookmarks TO service_role; ALTER TABLE public.bookmarks ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own bookmarks read" ON public.bookmarks FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Own bookmarks insert" ON public.bookmarks FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Own bookmarks delete" ON public.bookmarks FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.poll_votes (user_id uuid NOT NULL, post_id bigint NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, choice text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.poll_votes TO authenticated; GRANT ALL ON public.poll_votes TO service_role; ALTER TABLE public.poll_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own poll votes read" ON public.poll_votes FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Own poll votes insert" ON public.poll_votes FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Own poll votes update" ON public.poll_votes FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.follows (user_id uuid NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, target)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.follows TO authenticated; GRANT ALL ON public.follows TO service_role; ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own follows read" ON public.follows FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Own follows insert" ON public.follows FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Own follows delete" ON public.follows FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$; CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER posts_updated BEFORE UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER votes_updated BEFORE UPDATE ON public.post_votes FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER bookmarks_updated BEFORE UPDATE ON public.bookmarks FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER polls_updated BEFORE UPDATE ON public.poll_votes FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER follows_updated BEFORE UPDATE ON public.follows FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
