e morning only?','','poll',890,312,now()-interval '6 hours'),(15,'nneka_e','UNN','Campus','Walking through orientation week','','vertical-video',1120,64,now()-interval '26 hours'),(16,'amaka_o','UI','Academic','Voice note: how to survive your first semester','','audio',333,22,now()-interval '8 hours'),(17,'seyi_t','OAU','Campus','Faculty picnic snapshots','','four-three',215,12,now()-interval '60 hours'); SELECT setval('public.posts_id_seq', (SELECT max(id) FROM public.posts));